add([
(A2,"Назначение приложения","Приложение 2 к Договору поручения — перечни документов: для получения микрокредита, для лизинга, для кооперативов (адресовано претендентам/Заемщикам, документы принимает Поверенный).","Приложение 2, заголовок","Перечень документов для получения микрокредита"),
(A2,"Содержание (перечень документов/требований/показатели/форма)","Микрокредит, п. 1–4: анкета-заявление (оригинал/электронный); удостоверение личности заявителя/супруга, свидетельство о браке (копия/электронная/госбаза); согласие на сбор и обработку персональных данных и передачу в бюро кредитных историй; справки из обслуживающего банка о счете и просроченных кредитах (оригинал после одобрения микрокредита; копия, заверенная, с оригиналом в течение 30 календарных дней со дня выдачи).","Приложение 2, п. 1–4 (микрокредит)","допускается предоставление копии, заверенной уполномоченным лицом с оригиналом в течение 30 календарных дней со дня выдачи"),
(A2,"Содержание (перечень документов/требований/показатели/форма)","Микрокредит, п. 5–8: правоустанавливающие документы на залог (купля-продажа, дарение, приватизация, наследство, акты ввода в эксплуатацию, мена, технический паспорт, акт на земельный участок); справка о зарегистрированных правах (обременениях) на недвижимое имущество (Форма 2); отчет об оценке; соглашение гарантов о залоге имущества (оригинал).","Приложение 2, п. 5–8 (микрокредит)","Справка о зарегистрированных правах (обременениях) на недвижимое имущество и его технических характеристиках (Форма 2)"),
(A2,"Содержание (перечень документов/требований/показатели/форма)","Лизинг, п. 1–6: анкета-заявка на лизинг; документ, удостоверяющий личность заемщика/поручителя; согласие субъекта кредитной истории для бюро кредитных историй; согласие Заемщика/Гаранта на обработку персональных данных; правоустанавливающие документы поставщика на машины и оборудование (по согласованию); повторно анкета-заявка на лизинг (п. 6 дублирует п. 1).","Приложение 2, п. 1–6 (лизинг)","Правоустанавливающие документы поставщика на машины и оборудование (по согласованию)"),
(A2,"Содержание (перечень документов/требований/показатели/форма)","Кооперативы (микрозаймы), п. 1–8: протокол общего собрания участников; устав кооператива; устав; согласие на обработку персональных данных членов кооператива; сертификат об отсутствии задолженности; сертификат о существовании счета; протокол общего собрания и устав кооператива указаны повторно (п. 7–8).","Приложение 2, п. 1–8 (кооперативы)","Сертификат об отсутствии задолженности"),
(A3,"Назначение приложения","Приложение 3 к Договору поручения — требования к обеспечению (залогу); адресовано Заемщикам/Залогодателям и Поверенному.","Приложение 3, заголовок","Требования к обеспечению"),
(A3,"Содержание (перечень документов/требований/показатели/форма)","Допустимое обеспечение: недвижимость (право пользования) на праве собственности или аренды (залог прав краткосрочного временного возмездного и безвозмездного землепользования не допускается); недвижимость со справедливой рыночной стоимостью; недвижимость, свободная от обременений; движимое имущество (транспорт, с/х, дорожно-строительная и спецтехника, оборудование). Рыночная стоимость определяется с привлечением независимого оценщика.","Приложение 3, вводные абзацы","Определение рыночной (оценочной) стоимости предмета залога осуществляется с привлечением независимого оценщика."),
(A3,"Числовые значения (коэффициенты, сроки, пороги)","Наибольший коэффициент ликвидности: жилые здания — Астана/Алматы/Шымкент не более 0,8, региональные центры не более 0,7, другие НП не более 0,7; земли под жилую застройку — 0,8 / 0,6 / 0,5.","Приложение 3, таблица коэффициентов ликвидности, строки жилых зданий и земель под жилую застройку","Жилые здания (частные дома, квартиры), расположенные в:"),
(A3,"Числовые значения (коэффициенты, сроки, пороги)","Земли с/х назначения в частной собственности — не более 0,7; с долгосрочными правами землепользования более 10 лет (в т.ч. аренда, если срок аренды превышает срок кредита на 2 года и более) — не более 0,5.","Приложение 3, таблица, строки земель с/х назначения","Не более 0,5"),
(A3,"Числовые значения (коэффициенты, сроки, пороги)","Нежилые здания, сооружения — 0,7 (Астана/Алматы/Шымкент), 0,7 (региональные центры), 0,6 (другие НП); земли нежилого назначения — 0,8 / 0,7 / 0,6; машины, оборудование, транспортные средства — не более 0,5; финансовые активы — не более 1.","Приложение 3, таблица, строки нежилых зданий, земель нежилого назначения, машин и финансовых активов","Машины, оборудование, транспортные средства"),
(A3,"Числовые значения (коэффициенты, сроки, пороги)","Категории транспортных средств по возрасту: грузовые, автобусы (более 15 мест), легковые, микроавтобусы — сборка СНГ 5 лет, Китая/Кореи/США/Канады/Европы/Японии 10 лет; с/х техника (комбайны, сеялки и т.д.) — СНГ 15 лет, остальные страны 20 лет; дорожная техника и спецтехника — 20 лет.","Приложение 3, «Категория транспортного средства»","Дорожная техника и другая спецтехника - 20 лет"),
(A4,"Назначение приложения","Приложение 4 к Договору поручения — основные направления микрокредитования, требования к микрокредитам, запреты, требования к Заемщику и критерии отбора проектов (адресовано Претендентам/Заемщикам; ссылка в разд. «Основные условия займа», п. 9).","Приложение 4, заголовок","Основные направления микрокредитования"),
(A4,"Числовые значения (коэффициенты, сроки, пороги)","Направления: животноводство не более 40% от общего объема финансирования по региону; растениеводство; птицеводство; рыбоводство; с/х кооперативы и члены; переработка в АПК не более 20%; иные несельскохозяйственные направления, кроме купли-продажи; техника и оборудование — в форме лизинга.","Приложение 4, «Основные направления микрокредитования»","по направлению животноводства не более 40 (сорока) процентов от общего объема предоставленного финансирования по каждому региону"),
(A4,"Содержание (перечень документов/требований/показатели/форма)","Животноводство: собственное или арендуемое помещение/постройки для содержания животных; приобретаемые животные идентифицированы на имя продавца сроком не менее 6 месяцев.","Приложение 4, «Основные требования по микрокредитам в направлении животноводства»","идентифицированы в соответствии с Правилами идентификации сельскохозяйственных животных на имя продавца сроком не менее 6 месяцев"),
(A4,"Содержание (перечень документов/требований/показатели/форма)","Предпринимательство: заявитель обязуется сохранять статус ИП в течение срока договора. Запрещено финансирование: покупка легкового автомобиля; приобретение с/х животных у близких родственников; здания/объекты жилого назначения для сдачи в аренду (кроме туристско-рекреационных зон); оптовая и розничная торговля. Лизинг не предоставляется для покупки легкового автомобиля.","Приложение 4, «Основные требования по займам в направлении предпринимательства»; «Запрещается финансирование»","Запрещается финансирование на следующие цели"),
])
